import { existsSync, readFileSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { UI_SLOTS, type UiSlotSpec } from "@capybara-hq/plugin-sdk";
import {
  type Finding,
  isParseError,
  listSourceFiles,
  type Node,
  parseFile,
  walk,
} from "./source.js";

export type { Finding };

/** Where the generated files live, relative to the repository root. */
export const UI_SLOTS_TS = "apps/web/src/lib/ui-slots.generated.ts";
export const UI_SLOTS_DOC = "docs/guide/ui-slots.md";

const union = (values: readonly string[]) => values.map((v) => JSON.stringify(v)).join(" | ");
const list = (values: readonly string[]) => `[${values.map((v) => JSON.stringify(v)).join(", ")}]`;

/** The generated web copy of the slot catalog (the web app never imports the SDK). */
export function renderUiSlotsTs(slots: readonly UiSlotSpec[]): string {
  const scopes = [...new Set(slots.map((s) => s.scope))];
  const entries = slots.map((s) =>
    [
      `  ${JSON.stringify(s.id)}: {`,
      `    scope: ${JSON.stringify(s.scope)},`,
      `    accepts: ${list(s.accepts)},`,
      `    minRole: ${JSON.stringify(s.minRole)},`,
      `    args: ${list(s.args)},`,
      `    density: ${JSON.stringify(s.density)},`,
      `    anchors: ${list(s.anchors ?? [])},`,
      "  },",
    ].join("\n"),
  );
  return [
    "// Generated by pnpm gen:ui-slots from @capybara-hq/plugin-sdk; do not edit.",
    "",
    `export type UiSlotId =\n  | ${slots.map((s) => JSON.stringify(s.id)).join("\n  | ")};`,
    "",
    `export type UiSlotScope = ${union(scopes)};`,
    "",
    "export const UI_SLOT_SPECS: Record<",
    "  UiSlotId,",
    "  {",
    "    scope: UiSlotScope;",
    "    accepts: readonly string[];",
    "    minRole: string;",
    "    args: readonly string[];",
    "    density: string;",
    "    anchors: readonly string[];",
    "  }",
    "> = {",
    ...entries,
    "};",
    "",
  ].join("\n");
}

const code = (values: readonly string[]) =>
  values.length === 0 ? "none" : values.map((v) => `\`${v}\``).join(", ");

/** The generated docs page: a table of every slot and a section per slot. */
export function renderUiSlotsDoc(slots: readonly UiSlotSpec[]): string {
  const rows = slots.map(
    (s) =>
      `| \`${s.id}\` | ${s.scope} | ${code(s.accepts)} | ${s.minRole} | ${code(s.args)} | ${s.density} |`,
  );
  const sections = slots.map((s) =>
    [
      `## \`${s.id}\``,
      "",
      s.description.en,
      "",
      `- Version: ${s.version}`,
      `- Scope: ${s.scope}`,
      `- Accepts: ${code(s.accepts)}`,
      `- Minimum role: ${s.minRole}`,
      `- Args: ${code(s.args)}`,
      `- Density: ${s.density}`,
      `- Anchors: ${code(s.anchors ?? [])}`,
      `- Owner: \`apps/web/src/${s.owner}\``,
      "",
    ].join("\n"),
  );
  return [
    "<!-- Generated by pnpm gen:ui-slots from @capybara-hq/plugin-sdk; do not edit. -->",
    "",
    "# UI slots",
    "",
    "The places in the web app where extension UI can appear. Each slot has an id, a scope, the kinds",
    "of UI it accepts, the lowest role that sees it and the arguments it passes to the contribution.",
    "",
    "| Slot | Scope | Accepts | Min role | Args | Density |",
    "|---|---|---|---|---|---|",
    ...rows,
    "",
    ...sections,
  ].join("\n");
}

function staleFindings(root: string): Finding[] {
  const out: Finding[] = [];
  for (const [rel, expected] of [
    [UI_SLOTS_TS, renderUiSlotsTs(UI_SLOTS)],
    [UI_SLOTS_DOC, renderUiSlotsDoc(UI_SLOTS)],
  ] as const) {
    const file = join(root, rel);
    const actual = existsSync(file) ? readFileSync(file, "utf8") : undefined;
    if (actual === expected) continue;
    const a = (actual ?? "").split("\n");
    const e = expected.split("\n");
    let line = 0;
    while (line < e.length && a[line] === e[line]) line++;
    out.push({
      file,
      line: line + 1,
      rule: "ui-slots-stale",
      message:
        actual === undefined
          ? `${rel} is missing; run pnpm gen:ui-slots`
          : `${rel} differs from the SDK slot catalog; run pnpm gen:ui-slots (never edit it by hand)`,
    });
  }
  return out;
}

const SLOT_ELEMENT = "ExtensionSlot";

interface Render {
  file: string;
  line: number;
  slot: string;
  anchored: boolean;
}

/** Every `<ExtensionSlot slot=…>` under apps/web/src (not dev/); a non-literal `slot` is reported. */
function collectRenders(root: string, out: Finding[]): Render[] {
  const webSrc = join(root, "apps/web/src");
  const renders: Render[] = [];
  for (const { file } of listSourceFiles(webSrc)) {
    if (!file.endsWith(".tsx")) continue;
    if (relative(webSrc, file).split(sep)[0] === "dev") continue;
    const p = parseFile(file);
    if (isParseError(p)) {
      out.push(p);
      continue;
    }
    walk(p.program, (n) => {
      if (n.type !== "JSXOpeningElement") return;
      const name = n.name as Node;
      if (name.type !== "JSXIdentifier" || name.name !== SLOT_ELEMENT) return;
      const attrs = (n.attributes as Node[]).filter((a) => a.type === "JSXAttribute");
      const attr = (key: string) => attrs.find((a) => (a.name as Node).name === key);
      const line = p.lineOf(n.start);
      const value = attr("slot")?.value as Node | null | undefined;
      const inner = value?.type === "JSXExpressionContainer" ? (value.expression as Node) : value;
      const literal =
        inner?.type === "Literal" && typeof inner.value === "string" ? inner.value : undefined;
      if (literal === undefined) {
        out.push({
          file,
          line,
          rule: "ui-slot-literal",
          message: `the slot of <${SLOT_ELEMENT}> must be a string literal so the check can match it to the catalog`,
        });
        return;
      }
      renders.push({ file, line, slot: literal, anchored: attr("anchor") !== undefined });
    });
  }
  return renders;
}

/** Slots not rendered yet (client extensions plan, removed in Task 18). */
export const PENDING_SLOTS: ReadonlySet<string> = new Set([
  "shell.brand",
  "shell.overlay",
  "conversation.empty",
  "conversation.composer.frame",
]);

/**
 * check:ui-slots: every catalog slot is rendered once, by its owner file, through `<ExtensionSlot>`
 * (`ui-slot-literal`, `ui-slot-undeclared`, `ui-slot-unrendered`, `ui-slot-owner`, `ui-slot-twice`),
 * and the generated web copy and docs page equal what gen:ui-slots renders from the SDK catalog
 * (`ui-slots-stale`, only against the real catalog).
 */
export function checkUiSlots(root: string, slots: readonly UiSlotSpec[] = UI_SLOTS): Finding[] {
  const out: Finding[] = [];
  const renders = collectRenders(root, out);
  const webSrc = join(root, "apps/web/src");
  const byId = new Map(slots.map((s) => [s.id as string, s]));
  for (const r of renders) {
    const spec = byId.get(r.slot);
    if (!spec) {
      out.push({
        file: r.file,
        line: r.line,
        rule: "ui-slot-undeclared",
        message: `"${r.slot}" is not a slot of the catalog (packages/plugin-sdk/src/ui-slots.ts); add it there first`,
      });
    } else if (r.file !== join(webSrc, spec.owner)) {
      out.push({
        file: r.file,
        line: r.line,
        rule: "ui-slot-owner",
        message: `slot "${r.slot}" belongs to apps/web/src/${spec.owner}; render it there (UI slots spec §7)`,
      });
    }
  }
  for (const spec of slots) {
    const mine = renders.filter((r) => r.slot === spec.id);
    if (mine.length === 0) {
      if (PENDING_SLOTS.has(spec.id)) continue;
      out.push({
        file: join(webSrc, spec.owner),
        line: 1,
        rule: "ui-slot-unrendered",
        message: `slot "${spec.id}" has no <${SLOT_ELEMENT}> in apps/web/src; render it in its owner`,
      });
      continue;
    }
    // Several anchor renders of one list slot (one per built-in part) count as one.
    const anchored = mine.filter((r) => r.anchored);
    const counted = [...mine.filter((r) => !r.anchored), ...anchored.slice(0, 1)];
    const second = counted[1];
    if (second)
      out.push({
        file: second.file,
        line: second.line,
        rule: "ui-slot-twice",
        message: `slot "${spec.id}" is rendered more than once; render it in exactly one place`,
      });
  }
  if (slots === UI_SLOTS) out.push(...staleFindings(root));
  return out;
}
